IN[5]={"A1":"合理买入单价（用户成本法，元/m²）——值不值的问题","A2":"合理单价 =（有效年租金＋学位价值年化）÷（u − g）。u＝贷款比例×房贷利率＋（1−贷款比例）×R＋持有成本＋（买卖成本＋卖出时学位溢价损失）÷持有年限。学位价值只在两孩义务教育年份计入（右侧辅助表），按R折现后在持有期内年化，不再按永久年金计算。","K3":"学位价值辅助表（租房方预期额外学费）","A4":"贷款比例（按目标房源）","K4":"t","L4":"年份","M4":"在读孩子数","N4":"预期额外学费","O4":"计入(t≤H)","P4":"折现因子","A5":"加权房贷利率","K5":1,"A6":"（买卖成本＋学位溢价损失）年摊销","K6":2,"A7":"有效年租金（含搬家成本，元/m²）","K7":3,"A8":"学位价值现值（整套，持有期内）","K8":4,"A9":"学位价值年化（元/m²/年）","K9":5,"A10":"持有年化成本 u（按你认可的R）","K10":6,"A11":"合理单价（你认可的R、g；不含学位）","K11":7,"A12":"合理单价（你认可的R、g；含学位）","K12":8,"A13":"拟买价的有效租金回报率","K13":9,"A14":"盈亏平衡涨幅 g*（不含学位）","K14":10,"A15":"盈亏平衡涨幅 g*（含学位）","K15":11,"K16":12,"K17":13,"A18":"表A　不含学位","K18":14,"A19":"机会成本 R ↓ ／ 房价涨幅 g →","B19":-0.02,"C19":-0.01,"D19":0,"E19":0.01,"F19":0.015,"G19":0.02,"H19":0.025,"I19":0.03,"K19":15,"A20":0.017,"K20":16,"K21":17,"A22":0.035,"K22":18,"A23":0.045,"K23":19,"K24":20,"K25":21,"A26":"表B　含学位（学位价值年化按你认可的R计算）","K26":22,"A27":"机会成本 R ↓ ／ 房价涨幅 g →","B27":-0.02,"C27":-0.01,"D27":0,"E27":0.01,"F27":0.015,"G27":0.02,"H27":0.025,"I27":0.03,"K27":23,"A28":0.017,"K28":24,"K29":25,"A30":0.035,"K30":26,"A31":0.045,"K31":27,"K32":28,"K33":29,"A34":"读法：绿＝该情景合理价≥拟买价；红＝拟买价偏高。第二行R取自「资金配置」加权收益。","K34":30,"K35":31,"K36":32,"K37":33,"K38":34,"K39":35,"K40":36,"K41":37,"K42":38,"K43":39,"K44":40};
